     1→import {
     2→  type DesktopLocation,
     3→  locationToUrl,
     4→  buildViewTarget,
     5→  type BreadcrumbStackItem,
     6→  getDescriptorIcon,
     7→} from "./navigation-meta";
     8→
     9→// ─── Atomic Stack Operations ─────────────────────────────────────────────────
    10→
    11→export function getStackTop(
    12→  stack: BreadcrumbStackItem[]
    13→): BreadcrumbStackItem | undefined {
    14→  return stack[stack.length - 1];
    15→}
    16→
    17→export function pushStackItem(
    18→  stack: BreadcrumbStackItem[],
    19→  item: BreadcrumbStackItem
    20→): BreadcrumbStackItem[] {
    21→  return [...stack, item];
    22→}
    23→
    24→export function replaceStackTop(
    25→  stack: BreadcrumbStackItem[],
    26→  item: BreadcrumbStackItem
    27→): BreadcrumbStackItem[] {
    28→  if (stack.length === 0) {
    29→    return [item];
    30→  }
    31→
    32→  return [...stack.slice(0, -1), item];
    33→}
    34→
    35→export function popTo(
    36→  stack: BreadcrumbStackItem[],
    37→  index: number
    38→): BreadcrumbStackItem[] {
    39→  if (stack.length === 0) {
    40→    return stack;
    41→  }
    42→
    43→  const normalizedIndex = Math.max(0, Math.min(index, stack.length - 1));
    44→  return stack.slice(0, normalizedIndex + 1);
    45→}
    46→
    47→// ─── Item Factories ──────────────────────────────────────────────────────────
    48→
    49→export function createBreadcrumbItem(
    50→  item: Omit<BreadcrumbStackItem, "target"> & {
    51→    descriptorId?: string;
    52→    location?: DesktopLocation;
    53→  }
    54→): BreadcrumbStackItem {
    55→  return {
    56→    ...item,
    57→    icon: item.icon ?? getDescriptorIcon(item.descriptorId),
    58→    target: item.location
    59→      ? buildViewTarget(item.location, locationToUrl(item.location))
    60→      : undefined,
    61→  };
    62→}
    63→
    64→export function createLocationBreadcrumbItem(
    65→  location: DesktopLocation,
    66→  item: Partial<Omit<BreadcrumbStackItem, "target">> & {
    67→    descriptorId?: string;
    68→  }
    69→): BreadcrumbStackItem {
    70→  return createBreadcrumbItem({
    71→    id: item?.id ?? locationToUrl(location),
    72→    label: item?.label ?? locationToUrl(location),
    73→    icon: item?.icon,
    74→    meta: item?.meta,
    75→    parentNodeId: item?.parentNodeId,
    76→    sourceNodeId: item?.sourceNodeId,
    77→    descriptorId: item?.descriptorId,
    78→    location,
    79→  });
    80→}
