     1→import { useEffect, useRef, useState, type ReactNode } from "react";
     2→import { Check } from "lucide-react";
     3→import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
     4→import { Button } from "@/components/ui/button";
     5→import { IconDisplay } from "@/components/ui/icon-picker";
     6→import { cn } from "@/lib/utils";
     7→import type { BreadcrumbDropdownItem } from "@/navigation/page-index";
     8→
     9→interface BreadcrumbDropdownProps {
    10→  items: BreadcrumbDropdownItem[];
    11→  children: ReactNode;
    12→  onSelect?: (item: BreadcrumbDropdownItem) => void;
    13→  align?: "start" | "center" | "end";
    14→  className?: string;
    15→}
    16→
    17→export function BreadcrumbDropdown({
    18→  items,
    19→  children,
    20→  onSelect,
    21→  align = "start",
    22→  className,
    23→}: BreadcrumbDropdownProps) {
    24→  const [open, setOpen] = useState(false);
    25→  const closeTimerRef = useRef<number | null>(null);
    26→
    27→  useEffect(() => {
    28→    return () => {
    29→      if (closeTimerRef.current !== null) {
    30→        window.clearTimeout(closeTimerRef.current);
    31→      }
    32→    };
    33→  }, []);
    34→
    35→  if (items.length === 0) {
    36→    return <>{children}</>;
    37→  }
    38→
    39→  const clearCloseTimer = () => {
    40→    if (closeTimerRef.current !== null) {
    41→      window.clearTimeout(closeTimerRef.current);
    42→      closeTimerRef.current = null;
    43→    }
    44→  };
    45→
    46→  const handleOpen = () => {
    47→    clearCloseTimer();
    48→    setOpen(true);
    49→  };
    50→
    51→  const handleCloseSoon = () => {
    52→    clearCloseTimer();
    53→    closeTimerRef.current = window.setTimeout(() => {
    54→      setOpen(false);
    55→      closeTimerRef.current = null;
    56→    }, 120);
    57→  };
    58→
    59→  const handleSelect = (item: BreadcrumbDropdownItem) => {
    60→    item.onSelect?.();
    61→    onSelect?.(item);
    62→    setOpen(false);
    63→  };
    64→
    65→  return (
    66→    <Popover open={open} onOpenChange={setOpen}>
    67→      <PopoverTrigger asChild>
    68→        <span
    69→          className={cn("inline-flex", className)}
    70→          onMouseEnter={handleOpen}
    71→          onMouseLeave={handleCloseSoon}
    72→        >
    73→          {children}
    74→        </span>
    75→      </PopoverTrigger>
    76→      <PopoverContent
    77→        align={align}
    78→        side="bottom"
    79→        sideOffset={6}
    80→        className="w-72 p-1.5"
    81→        onMouseEnter={handleOpen}
    82→        onMouseLeave={handleCloseSoon}
    83→      >
    84→        <div className="max-h-80 overflow-y-auto">
    85→          {items.map((item) => (
    86→            <Button
    87→              key={item.id}
    88→              type="button"
    89→              variant="ghost"
    90→              size="sm"
    91→              className={cn(
    92→                "h-auto w-full items-start justify-start gap-3 rounded-lg px-2.5 py-2 text-left text-sm hover:translate-y-0",
    93→                "bg-transparent focus-visible:bg-accent/40 data-[state=open]:bg-transparent",
    94→                item.isActive && "bg-accent text-accent-foreground hover:bg-accent"
    95→              )}
    96→              onClick={() => handleSelect(item)}
    97→            >
    98→              <IconDisplay
    99→                icon={item.icon}
   100→                size="sm"
   101→                className="mt-0.5 text-muted-foreground"
   102→              />
   103→              <span className="min-w-0 flex-1">
   104→                <span className="block truncate text-sm font-medium">
   105→                  {item.label}
   106→                </span>
   107→                {item.description ? (
   108→                  <span className="block truncate text-xs text-muted-foreground">
   109→                    {item.description}
   110→                  </span>
   111→                ) : null}
   112→              </span>
   113→              {item.isActive ? (
   114→                <Check className="mt-0.5 h-4 w-4 text-primary" />
   115→              ) : null}
   116→            </Button>
   117→          ))}
   118→        </div>
   119→      </PopoverContent>
   120→    </Popover>
   121→  );
   122→}
   123→

