   102→
   103→function buildDropdownItems<T>(
   104→  items: T[],
   105→  mapItem: (item: T, index: number) => BreadcrumbDropdownItem | null | undefined
   106→): BreadcrumbDropdownItem[] {
   107→  return items
   108→    .map((item, index) => mapItem(item, index))
