   180→
   181→export function resolveHeaderSegments(input: {
   182→  stack?: BreadcrumbStackItem[];
   183→  fallback?: DesktopBreadcrumbSegment[];
   184→  patchLast?: Partial<DesktopBreadcrumbSegment> & {
   185→    meta?: DesktopBreadcrumbSegment["meta"];
   186→  };
   187→}): DesktopBreadcrumbSegment[] {
   188→  const stackSegments = stackToDesktopSegments(input.stack);
   189→  const patchLast = input.patchLast;
   190→
   191→  if (stackSegments.length === 0) {
   192→    return input.fallback ?? [];
   193→  }
   194→
   195→  if (!patchLast) {
   196→    return stackSegments;
   197→  }
   198→
   199→  return stackSegments.map((segment, index, segments) =>
   200→    index === segments.length - 1
   201→      ? {
   202→          ...segment,
   203→          ...patchLast,
   204→          meta: {
   205→            ...segment.meta,
   206→            ...patchLast.meta,
   207→          },
   208→        }
   209→      : segment
   210→  );
   211→}
