    14→import type { BreadcrumbStackItem } from "@/navigation/navigation-meta";
    15→import type { Workspace } from "@/types";
    16→
    17→interface NavigationShellHeaderState {
    18→  workspace?: Workspace;
    19→  segments?: DesktopBreadcrumbSegment[];
    20→  className?: string;
    21→}
    22→
    23→interface RegisteredNavigationShellHeader extends NavigationShellHeaderState {
    24→  ownerId: string;
    25→}
    26→
    27→interface NavigationShellActionsContextValue {
    28→  setHeader: (ownerId: string, next: NavigationShellHeaderState) => void;
    29→  clearHeader: (ownerId: string) => void;
    30→  setCenterContent: (ownerId: string, content: ReactNode | null) => void;
    31→  setRightContent: (ownerId: string, content: ReactNode | null) => void;
    32→  clearSlotContent: (ownerId: string) => void;
    33→}
    34→
    35→interface NavigationShellSlotsContextValue {
    36→  centerHost: HTMLDivElement | null;
    37→  rightHost: HTMLDivElement | null;
    38→  setCenterHost: (node: HTMLDivElement | null) => void;
    39→  setRightHost: (node: HTMLDivElement | null) => void;
    40→  centerContent: ReactNode | null;
    41→  rightContent: ReactNode | null;
    42→}
    43→
    44→const NavigationShellHeaderContext =
    45→  createContext<RegisteredNavigationShellHeader | null>(null);
    46→const NavigationShellActionsContext =
    47→  createContext<NavigationShellActionsContextValue | null>(null);
    48→const NavigationShellSlotsContext =
    49→  createContext<NavigationShellSlotsContextValue | null>(null);
    50→
    51→const EMPTY_SEGMENTS: DesktopBreadcrumbSegment[] = [];
    52→
    53→function areHeadersEqual(
    54→  current: RegisteredNavigationShellHeader | null,
    55→  ownerId: string,
    56→  next: NavigationShellHeaderState
    57→): boolean {
    58→  const currentWorkspaceId = current?.workspace?.id;
    59→  const nextWorkspaceId = next.workspace?.id;
    60→  const currentSegments = JSON.stringify(current?.segments ?? []);
    61→  const nextSegments = JSON.stringify(next.segments ?? []);
    62→
    63→  return (
    64→    current?.ownerId === ownerId &&
    65→    currentWorkspaceId === nextWorkspaceId &&
    66→    currentSegments === nextSegments &&
    67→    current.className === next.className
    68→  );
    69→}
    70→
    71→function mapStackItemToSegment(
    72→  item: BreadcrumbStackItem
    73→): DesktopBreadcrumbSegment {
    74→  return {
    75→    id: item.id,
    76→    label: item.label,
    77→    href: item.target?.canonicalUrl ?? "#",
    78→    icon: item.icon,
    79→    descriptorId: item.descriptorId,
    80→    meta: item.meta,
    81→  };
    82→}
    83→
    84→function buildDerivedHeader(
    85→  stack: BreadcrumbStackItem[] | undefined,
    86→  workspaces: Workspace[]
    87→): NavigationShellHeaderState | null {
    88→  if (!stack?.length) {
    89→    return null;
    90→  }
    91→
    92→  const [root, ...rest] = stack;
    93→  if (root.descriptorId === "workspace" && root.meta?.workspaceId) {
    94→    const workspace = workspaces.find(
    95→      (item) => item.id === root.meta?.workspaceId
    96→    );
    97→
    98→    if (workspace) {
    99→      return {
   100→        workspace,
   101→        segments: rest.map(mapStackItemToSegment),
   102→      };
   103→    }
   104→  }
   105→
   106→  return {
   107→    segments: stack.map(mapStackItemToSegment),
   108→  };
   109→}
   110→
   111→export function NavigationShellProvider({
   112→  children,
   113→}: {
   114→  children: ReactNode;
   115→}) {
   116→  const [header, setHeaderState] =
   117→    useState<RegisteredNavigationShellHeader | null>(null);
   118→  const [centerContent, setCenterContentState] = useState<ReactNode | null>(null);
   119→  const [rightContent, setRightContentState] = useState<ReactNode | null>(null);
   120→  const [centerHost, setCenterHost] = useState<HTMLDivElement | null>(null);
   121→  const [rightHost, setRightHost] = useState<HTMLDivElement | null>(null);
   122→  const slotOwnerRef = useRef<string | null>(null);
   123→
   124→  const setHeader = useCallback(
   125→    (ownerId: string, next: NavigationShellHeaderState) => {
   126→      setHeaderState((current) => {
   127→        if (areHeadersEqual(current, ownerId, next)) {
   128→          return current;
   129→        }
   130→
   131→        return {
   132→          ownerId,
   133→          ...next,
   134→        };
   135→      });
   136→    },
   137→    []
   138→  );
   139→
   140→  const clearHeader = useCallback((ownerId: string) => {
   141→    setHeaderState((current) =>
   142→      current?.ownerId === ownerId ? null : current
   143→    );
   144→  }, []);
   145→
   146→  const setCenterContent = useCallback((ownerId: string, content: ReactNode | null) => {
   147→    slotOwnerRef.current = ownerId;
   148→    setCenterContentState(content);
   149→  }, []);
   150→
   151→  const setRightContent = useCallback((ownerId: string, content: ReactNode | null) => {
   152→    slotOwnerRef.current = ownerId;
   153→    setRightContentState(content);
   154→  }, []);
   155→
   156→  const clearSlotContent = useCallback((ownerId: string) => {
   157→    if (slotOwnerRef.current !== ownerId) {
   158→      return;
   159→    }
   160→
   161→    slotOwnerRef.current = null;
   162→    setCenterContentState(null);
   163→    setRightContentState(null);
   164→  }, []);
   165→
   166→  const actionsValue = useMemo(
   167→    () => ({
   168→      setHeader,
   169→      clearHeader,
   170→      setCenterContent,
   171→      setRightContent,
   172→      clearSlotContent,
   173→    }),
   174→    [clearHeader, clearSlotContent, setCenterContent, setHeader, setRightContent]
   175→  );
   176→  const slotsValue = useMemo(
   177→    () => ({
   178→      centerHost,
   179→      rightHost,
   180→      setCenterHost,
   181→      setRightHost,
   182→      centerContent,
   183→      rightContent,
   184→    }),
   185→    [centerContent, centerHost, rightContent, rightHost]
   186→  );
   187→
   188→  return (
   189→    <NavigationShellActionsContext.Provider value={actionsValue}>
   190→      <NavigationShellSlotsContext.Provider value={slotsValue}>
   191→        <NavigationShellHeaderContext.Provider value={header}>
   192→          {children}
   193→        </NavigationShellHeaderContext.Provider>
   194→      </NavigationShellSlotsContext.Provider>
   195→    </NavigationShellActionsContext.Provider>
   196→  );
   197→}
   198→
   199→export function useOptionalNavigationShell() {
   200→  return useContext(NavigationShellActionsContext);
   201→}
   202→
   203→export function useNavigationShellHeaderState() {
   204→  return useContext(NavigationShellHeaderContext);
   205→}
   206→
   207→export function useNavigationShellSlots() {
   208→  return useContext(NavigationShellSlotsContext);
   209→}
   210→
   211→export function GlobalBreadcrumbShell() {
   212→  const registeredHeader = useContext(NavigationShellHeaderContext);
   213→  const slots = useContext(NavigationShellSlotsContext);
   214→  const { currentNavigationState } = useActiveTabState();
   215→  const { workspaces } = useLocalWorkspaces();
   216→
   217→  const derivedHeader = useMemo(
   218→    () => buildDerivedHeader(currentNavigationState?.breadcrumbStack, workspaces),
   219→    [currentNavigationState?.breadcrumbStack, workspaces]
   220→  );
   221→
   222→  const resolvedHeader = useMemo(() => {
   223→    if (!registeredHeader && !derivedHeader) {
   224→      return null;
   225→    }
   226→
   227→    return {
   228→      workspace: derivedHeader?.workspace ?? registeredHeader?.workspace,
   229→      segments: derivedHeader?.segments ?? registeredHeader?.segments ?? EMPTY_SEGMENTS,
   230→      className: registeredHeader?.className,
   231→    };
   232→  }, [derivedHeader, registeredHeader]);
   233→
   234→  if (!resolvedHeader) {
   235→    return null;
   236→  }
   237→
   238→  const handleCenterHostRef = useCallback(
   239→    (node: HTMLDivElement | null) => {
   240→      slots?.setCenterHost(node);
   241→    },
   242→    [slots]
   243→  );
   244→
   245→  const handleRightHostRef = useCallback(
   246→    (node: HTMLDivElement | null) => {
   247→      slots?.setRightHost(node);
   248→    },
   249→    [slots]
   250→  );
   251→
   252→  return (
   253→    <DesktopBreadcrumbBar
   254→      workspace={resolvedHeader.workspace}
   255→      segments={resolvedHeader.segments}
   256→      className={resolvedHeader.className}
   257→      centerSlot={
   258→        <div
   259→          ref={handleCenterHostRef}
   260→          className="flex min-w-0 items-center justify-center"
   261→        >
   262→          {slots?.centerContent}
   263→        </div>
   264→      }
   265→      rightSlot={
   266→        <div
   267→          ref={handleRightHostRef}
   268→          className="flex items-center gap-2"
   269→        >
   270→          {slots?.rightContent}
   271→        </div>
   272→      }
   273→    />
   274→  );
   275→}
