   490→    transition,
   491→  };
   492→
   493→  return (
   494→    <PageTreeItemContent
   495→      {...props}
   496→      isDragging={isDragging}
   497→      sortableStyle={style}
   498→      sortableRef={setNodeRef}
   499→      sortableAttributes={attributes as unknown as Record<string, unknown>}
